import java.io.BufferedReader;
import java.io.InputStreamReader;
import java.io.PrintWriter;
import java.util.StringTokenizer;

public class EducationalRound86E_Variant3 {

    static final long MOD = 998244353;
    static final int MAX = (int)4e5 + 10;
    static long[] factArr;
    static long[] invFactArr;

    static void computeFactorials() {
        factArr = new long[MAX];
        invFactArr = new long[MAX];
        factArr[0] = 1;
        invFactArr[0] = 1;
        for (int i = 1; i < MAX; i++) {
            factArr[i] = (factArr[i - 1] * i) % MOD;
            invFactArr[i] = (invFactArr[i - 1] * modInverse(i, MOD)) % MOD;
        }
    }

    static long nCr(int n, int r) {
        return (factArr[n] * invFactArr[r] % MOD) * invFactArr[n - r] % MOD;
    }

    static long power(long base, long exp) {
        long result = 1;
        long b = base % MOD;
        long e = exp;
        while (e > 0) {
            if ((e & 1) == 1) result = (result * b) % MOD;
            b = (b * b) % MOD;
            e >>= 1;
        }
        return result;
    }

    static void process() {
        computeFactorials();
        int n = s.nextInt();
        long k = s.nextLong();
        if (k == 0) {
            out.println(factArr[n]);
            return;
        }
        if (n <= k) {
            out.println(0);
            return;
        }
        long ans = nCr(n, (int)k);
        int remaining = n - (int)k;
        long totalSum = 0;
        for (int i = 0; i <= remaining; i++) {
            long temp = nCr(remaining, i);
            temp = (temp * power(remaining - i, n)) % MOD;
            if ((i & 1) == 1) {
                totalSum -= temp;
                if (totalSum < 0) totalSum += MOD;
            } else {
                totalSum += temp;
                if (totalSum >= MOD) totalSum -= MOD;
            }
        }
        out.println((2 * ((ans * totalSum) % MOD)) % MOD);
    }

    public static void main(String[] args) {
        out = new PrintWriter(System.out);
        s = new FastReader();
        process();
        out.close();
    }

    static class Triplet {
        long g, x, y;
        Triplet(long g, long x, long y) {
            this.g = g; this.x = x; this.y = y;
        }
    }

    static Triplet extendedEuclid(long a, long b) {
        if (a == 0) return new Triplet(b, 0, 1);
        Triplet res = extendedEuclid(b % a, a);
        long x = res.y - (b / a) * res.x;
        long y = res.x;
        return new Triplet(res.g, x, y);
    }

    static long modInverse(long a, long m) {
        Triplet res = extendedEuclid(a, m);
        if (res.g != 1) return -1;
        return (res.x % m + m) % m;
    }

    static FastReader s;
    static PrintWriter out;

    static class FastReader {
        BufferedReader br;
        StringTokenizer st;
        FastReader() {
            br = new BufferedReader(new InputStreamReader(System.in));
        }
        String next() {
            while (st == null || !st.hasMoreTokens()) {
                try { st = new StringTokenizer(br.readLine()); } catch (Exception e) { e.printStackTrace(); }
            }
            return st.nextToken();
        }
        int nextInt() { return Integer.parseInt(next()); }
        long nextLong() { return Long.parseLong(next()); }
    }
}
